import type {
  EncryptedRuntimeRecoveryBundleV1,
  TowerAppointmentV1,
  TowerLastResortPayloadV1,
  TowerModeV1,
  TowerReceiptV1,
} from '../../storage/recovery/bundle/types';
import { normalizeTowerModeV1 } from '../../storage/recovery/bundle/types';
import {
  computeEncryptedRuntimeRecoveryEnvelopeHash,
  computeTowerLastResortPayloadDigest,
} from '../../storage/recovery/bundle/crypto';
import { deserializeTaggedJson } from '../../protocol/serialization';
import { requireBoundaryRecord } from '../../protocol/boundary-validation';
import {
  computeStoredLookupBytes,
  emptyStoredDoc,
  ensureWatchtowerStoreOpen,
  normalizeLookupKey,
  readLookup,
  runSerializedAppointmentWrite,
  writeLookup,
} from './db';
import type { LastResortTowerAppointment, StoredLookupDoc, WatchtowerStoreContext } from './types';
import { decodeStoredLookupDoc, decodeWatchtowerStoredValue } from './decode';

const towerModeOf = (appointment: TowerAppointmentV1): TowerModeV1 => normalizeTowerModeV1(appointment.towerMode);

const slotOf = (appointment: TowerAppointmentV1): number => Math.max(0, Math.floor(Number(appointment.slot ?? 0)));

const assertEncryptedLastResortPayload = (payload: TowerLastResortPayloadV1 | null | undefined): void => {
  const raw = String(payload?.encryptedRemedy || '').trim();
  if (!raw) throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_MISSING');
  let parsed: Record<string, unknown>;
  try {
    parsed = requireBoundaryRecord(deserializeTaggedJson(raw), 'TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  } catch {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  }
  if (
    parsed['type'] !== 'tower_encrypted_payload' ||
    parsed['version'] !== 1 ||
    parsed['alg'] !== 'watch-seed-aes-256-gcm' ||
    typeof parsed['iv'] !== 'string' ||
    typeof parsed['ciphertext'] !== 'string'
  ) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  }
};

const buildReceiptMessage = (receipt: TowerReceiptV1): string =>
  `xln:watchtower:receipt:v1|${receipt.towerId}|${receipt.lookupKey}|${receipt.runtimeId}|${receipt.height}|${receipt.bundleHash}|${Math.max(0, Math.floor(Number(receipt.sequence || 0)))}|${Math.max(0, Math.floor(Number(receipt.slot || 0)))}|${String(receipt.towerMode || 'blind_backup')}|${Math.max(0, Math.floor(Number(receipt.storedBytes || 0)))}|${Math.max(0, Math.floor(Number(receipt.maxStoredBytes || 0)))}|${Math.max(0, Math.floor(Number(receipt.expiresAt || 0)))}`;

const sortStoredBundles = (bundles: StoredLookupDoc['bundles']): StoredLookupDoc['bundles'] =>
  bundles.sort((left, right) => {
    if (right.bundle.height !== left.bundle.height) return right.bundle.height - left.bundle.height;
    if (right.bundle.createdAt !== left.bundle.createdAt) return right.bundle.createdAt - left.bundle.createdAt;
    return right.slot - left.slot;
  });

const retainAppointmentBundles = (
  bundles: StoredLookupDoc['bundles'],
  towerMode: TowerModeV1,
  limit: number,
): StoredLookupDoc['bundles'] => {
  const pinned: StoredLookupDoc['bundles'] = [];
  const pin = (entry: StoredLookupDoc['bundles'][number] | undefined): void => {
    if (entry && !pinned.includes(entry)) pinned.push(entry);
  };
  if (towerMode === 'blind_backup') {
    pin(bundles.find(entry => entry.towerMode === 'blind_backup' && entry.bundle.kind !== 'journal_tail'));
    pin(bundles.find(entry => entry.towerMode === 'blind_backup' && entry.bundle.kind === 'journal_tail'));
  }
  return [...pinned, ...bundles.filter(entry => !pinned.includes(entry))].slice(0, limit);
};

const validateAppointmentMode = (appointment: TowerAppointmentV1, towerMode: TowerModeV1): void => {
  if (towerMode === 'blind_backup' && appointment.lastResortPayload) {
    throw new Error('TOWER_BACKUP_LAST_RESORT_PAYLOAD_FORBIDDEN');
  }
  if (towerMode === 'delayed_last_resort' && !appointment.lastResortPayload) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_MISSING');
  }
  if (towerMode === 'delayed_last_resort') {
    assertEncryptedLastResortPayload(appointment.lastResortPayload);
  }
};

const prepareAppointment = async (
  context: WatchtowerStoreContext,
  appointment: TowerAppointmentV1,
  existing: StoredLookupDoc,
): Promise<StoredLookupDoc> => {
  const lookupKey = normalizeLookupKey(appointment.lookupKey);
  const towerMode = towerModeOf(appointment);
  const slot = slotOf(appointment);
  validateAppointmentMode(appointment, towerMode);
  const runtimeId = String(appointment.bundle.runtimeId || '')
    .trim()
    .toLowerCase();
  if (existing.runtimeId && existing.runtimeId !== runtimeId) {
    throw new Error(`TOWER_LOOKUP_RUNTIME_ID_MISMATCH:${existing.runtimeId}:${runtimeId}`);
  }
  const sequence = Math.max(0, ...existing.receipts.map(receipt => receipt.sequence || 0)) + 1;
  const ownerSignedAt = Math.max(0, Math.floor(Number(appointment.ownerProof.signedAt || 0)));
  const lastResortPayloadDigest = computeTowerLastResortPayloadDigest(appointment.lastResortPayload);
  const encryptedEnvelopeHash = computeEncryptedRuntimeRecoveryEnvelopeHash(appointment.bundle);
  const sameSlotEntries = existing.bundles.filter(
    entry =>
      entry.slot === slot
      && entry.towerMode === towerMode
      && (entry.bundle.kind ?? 'snapshot') === (appointment.bundle.kind ?? 'snapshot'),
  );
  const latestSameSlot = sameSlotEntries.reduce<(typeof sameSlotEntries)[number] | undefined>(
    (latest, entry) => !latest || entry.ownerSignedAt > latest.ownerSignedAt ? entry : latest,
    undefined,
  );
  if (latestSameSlot && latestSameSlot.ownerSignedAt > ownerSignedAt) {
    throw new Error('TOWER_APPOINTMENT_STALE');
  }
  if (
    latestSameSlot
    && latestSameSlot.ownerSignedAt === ownerSignedAt
    && (
      latestSameSlot.encryptedEnvelopeHash !== encryptedEnvelopeHash
      || latestSameSlot.lastResortPayloadDigest !== lastResortPayloadDigest
    )
  ) {
    throw new Error('TOWER_APPOINTMENT_REPLAY_MISMATCH');
  }
  const candidate = {
    slot,
    towerMode,
    bundle: appointment.bundle,
    ownerSignedAt,
    encryptedEnvelopeHash,
    lastResortPayloadDigest,
    ...(appointment.lastResortPayload ? { lastResortPayload: structuredClone(appointment.lastResortPayload) } : {}),
  };
  const sortedBundles = sortStoredBundles([
    candidate,
    ...existing.bundles.filter(entry =>
      entry.slot !== slot
      || entry.towerMode !== towerMode
      || (entry.bundle.kind ?? 'snapshot') !== (appointment.bundle.kind ?? 'snapshot')),
  ]);
  const nextBundles = retainAppointmentBundles(sortedBundles, towerMode, context.maxBundlesPerLookupKey);
  const nextDoc: StoredLookupDoc = {
    lookupKey,
    runtimeId,
    updatedAt: context.now(),
    receipts: existing.receipts,
    bundles: nextBundles,
  };
  const storedBytes = computeStoredLookupBytes(nextDoc);
  if (storedBytes > context.maxStoredBytesPerLookupKey) {
    throw new Error(`TOWER_QUOTA_EXCEEDED: bytes=${storedBytes} max=${context.maxStoredBytesPerLookupKey}`);
  }
  const unsignedReceipt: TowerReceiptV1 = {
    type: 'tower_receipt',
    version: 1,
    towerId: context.towerId,
    lookupKey,
    runtimeId,
    height: Math.max(0, Math.floor(Number(appointment.bundle.height || 0))),
    bundleHash: appointment.bundle.bundleHash,
    towerMode,
    slot,
    storedAt: nextDoc.updatedAt,
    receivedAt: nextDoc.updatedAt,
    expiresAt: nextDoc.updatedAt + context.receiptTtlMs,
    sequence,
    retainedSlots: nextBundles.length,
    storedBytes,
    maxStoredBytes: context.maxStoredBytesPerLookupKey,
    quotaOk: true,
    appointmentSequence: Number.isFinite(Number(appointment.lastResortPayload?.appointmentSequence))
      ? Math.max(0, Math.floor(Number(appointment.lastResortPayload?.appointmentSequence || 0)))
      : null,
  };
  const receipt = {
    ...unsignedReceipt,
    towerSignature: await context.signer.signMessage(buildReceiptMessage(unsignedReceipt)),
  };
  nextDoc.receipts = [receipt, ...existing.receipts].slice(0, context.maxBundlesPerLookupKey);
  return nextDoc;
};

export const upsertAppointment = async (
  context: WatchtowerStoreContext,
  appointment: TowerAppointmentV1,
): Promise<TowerReceiptV1> => runSerializedAppointmentWrite(
  context,
  async () => {
    const key = normalizeLookupKey(appointment.lookupKey);
    const doc = await prepareAppointment(context, appointment, await readLookup(context, key) ?? emptyStoredDoc(key));
    await writeLookup(context, doc);
    return doc.receipts[0]!;
  },
);

/** One owner-signed checkpoint and matching tail, published as one lookup document. */
export const upsertRecoveryArchive = async (
  context: WatchtowerStoreContext,
  appointments: readonly [TowerAppointmentV1, TowerAppointmentV1],
): Promise<TowerReceiptV1> => runSerializedAppointmentWrite(context, async () => {
  const [snapshot, tail] = appointments;
  if (appointments.some(item => towerModeOf(item) !== 'blind_backup') ||
      snapshot.bundle.kind !== 'snapshot' || tail.bundle.kind !== 'journal_tail' ||
      snapshot.lookupKey !== tail.lookupKey || snapshot.bundle.runtimeId !== tail.bundle.runtimeId ||
      slotOf(snapshot) !== slotOf(tail) ||
      snapshot.ownerProof.signedAt !== tail.ownerProof.signedAt ||
      tail.bundle.baseRuntimeHeight !== snapshot.bundle.height || tail.bundle.height <= snapshot.bundle.height)
    throw new Error('TOWER_ARCHIVE_PAIR_INVALID');
  const key = normalizeLookupKey(snapshot.lookupKey);
  let doc = await readLookup(context, key) ?? emptyStoredDoc(key);
  for (const appointment of appointments) doc = await prepareAppointment(context, appointment, doc);
  for (const appointment of appointments) {
    if (!doc.bundles.some(entry => entry.encryptedEnvelopeHash === computeEncryptedRuntimeRecoveryEnvelopeHash(appointment.bundle)))
      throw new Error('TOWER_ARCHIVE_PAIR_NOT_RETAINED');
  }
  // Signature, stale/replay, retention and quota failures leave the prior complete
  // document intact. The blind tower binds visible identity/base metadata; the
  // recipient additionally authenticates and matches the encrypted checkpoint hash.
  await writeLookup(context, doc);
  return doc.receipts[0]!;
});

export const getLatest = async (
  context: WatchtowerStoreContext,
  lookupKey: string,
): Promise<{
  receipt: TowerReceiptV1;
  bundle: EncryptedRuntimeRecoveryBundleV1;
  bundles: EncryptedRuntimeRecoveryBundleV1[];
} | null> => {
  const existing = await readLookup(context, lookupKey);
  if (!existing || existing.receipts.length === 0 || existing.bundles.length === 0) return null;
  const sorted = sortStoredBundles([...existing.bundles]);
  const snapshots = sorted.filter(entry => entry.towerMode === 'blind_backup' && entry.bundle.kind !== 'journal_tail');
  const journalTails = sorted.filter(
    entry => entry.towerMode === 'blind_backup' && entry.bundle.kind === 'journal_tail',
  );
  const candidates = snapshots
    .map(snapshot => {
      const tail = journalTails.find(
        entry =>
          entry.bundle.baseRuntimeHeight === snapshot.bundle.height && entry.bundle.height >= snapshot.bundle.height,
      );
      return { snapshot, tail, height: tail?.bundle.height ?? snapshot.bundle.height };
    })
    .sort((left, right) =>
      right.height !== left.height
        ? right.height - left.height
        : right.snapshot.bundle.height - left.snapshot.bundle.height,
    );
  const best = candidates[0];
  const bundles = best
    ? best.tail
      ? [best.snapshot.bundle, best.tail.bundle]
      : [best.snapshot.bundle]
    : [existing.bundles[0]!.bundle];
  return {
    receipt: existing.receipts[0]!,
    bundle: bundles[bundles.length - 1]!,
    bundles,
  };
};

export const getLatestReceipt = async (
  context: WatchtowerStoreContext,
  lookupKey: string,
): Promise<TowerReceiptV1 | null> => {
  const existing = await readLookup(context, lookupKey);
  return existing?.receipts[0] || null;
};

const compareLastResortBundles = (
  left: StoredLookupDoc['bundles'][number],
  right: StoredLookupDoc['bundles'][number],
): number => {
  const leftSequence = Math.max(0, Math.floor(Number(left.lastResortPayload?.appointmentSequence || 0)));
  const rightSequence = Math.max(0, Math.floor(Number(right.lastResortPayload?.appointmentSequence || 0)));
  if (rightSequence !== leftSequence) return rightSequence - leftSequence;
  const leftNonce = Math.max(0, Math.floor(Number(left.lastResortPayload?.proofNonce || 0)));
  const rightNonce = Math.max(0, Math.floor(Number(right.lastResortPayload?.proofNonce || 0)));
  if (rightNonce !== leftNonce) return rightNonce - leftNonce;
  if (right.bundle.height !== left.bundle.height) return right.bundle.height - left.bundle.height;
  if (right.bundle.createdAt !== left.bundle.createdAt) return right.bundle.createdAt - left.bundle.createdAt;
  return right.slot - left.slot;
};

/**
 * Minimum appointment sequence that fences out every appointment in `appointments`
 * (EntityProvider.setWatchtowerMinSequence): one above the highest stored
 * appointmentSequence. Returns 1n when nothing is stored (the contract requires
 * newMinimum > current minimum > 0).
 */
export const watchtowerMinSequenceRevokingAll = (
  appointments: ReadonlyArray<Pick<LastResortTowerAppointment, 'lastResortPayload'>>,
): bigint => {
  let highest = 0n;
  for (const appointment of appointments) {
    const raw = Number(appointment.lastResortPayload?.appointmentSequence ?? 0);
    if (!Number.isFinite(raw) || raw <= 0) continue;
    const sequence = BigInt(Math.floor(raw));
    if (sequence > highest) highest = sequence;
  }
  return highest + 1n;
};

export const listLatestLastResortAppointments = async (
  context: WatchtowerStoreContext,
): Promise<LastResortTowerAppointment[]> => {
  await ensureWatchtowerStoreOpen(context);
  const appointments: LastResortTowerAppointment[] = [];
  for await (const [key, raw] of context.db.iterator({ gte: 'lookup:', lte: 'lookup:\xff' })) {
    const doc = decodeWatchtowerStoredValue('lookup', String(key), String(raw), decodeStoredLookupDoc);
    const entry = doc.bundles
      .filter(candidate => candidate.towerMode === 'delayed_last_resort' && !!candidate.lastResortPayload)
      .sort(compareLastResortBundles)[0];
    if (!entry?.lastResortPayload) continue;
    appointments.push({
      lookupKey: doc.lookupKey,
      runtimeId: doc.runtimeId,
      towerMode: entry.towerMode,
      slot: entry.slot,
      bundle: entry.bundle,
      lastResortPayload: structuredClone(entry.lastResortPayload),
    });
  }
  return appointments;
};

import { ethers } from 'ethers';
import { deserializeTaggedJson, serializeTaggedJson } from '../protocol/serialization';
import {
  requireBoundaryRecord,
  requireExactBoundaryKeys,
} from '../protocol/boundary-validation';
import type {
  TowerAppointmentV1,
  TowerDiscoverResponseV1,
  TowerRestoreRequestV1,
  TowerRestoreResponseV1,
} from '../storage/recovery/bundle/types';
import { normalizeTowerModeV1 } from '../storage/recovery/bundle/types';
import {
  buildTowerAppointmentOwnerMessage,
} from '../storage/recovery/bundle/crypto';
import type { WatchtowerStore } from './store';
import { WatchtowerGlobalQuotaError } from './store/db';
import { runWatchtowerSweep } from './action';
import type { PushStore } from './push/store';
import {
  PUSH_REGISTRATION_MAX_CLOCK_SKEW_MS,
  verifyPushRegistration,
  verifyPushUnregister,
} from './push/registration';

const DEFAULT_MAX_JSON_BODY_BYTES = 128 * 1024;
const SMALL_MAX_JSON_BODY_BYTES = 8 * 1024;
const APPOINTMENT_ENVELOPE_MAX_BYTES = 64 * 1024;
const TOWER_APPOINTMENT_MAX_CLOCK_SKEW_MS = 24 * 60 * 60 * 1000;

export const resolveAppointmentBodyLimit = (store: Pick<WatchtowerStore, 'maxStoredBytesPerLookupKey'>): number =>
  Math.max(
    DEFAULT_MAX_JSON_BODY_BYTES,
    store.maxStoredBytesPerLookupKey + APPOINTMENT_ENVELOPE_MAX_BYTES,
  );

const parseContentLength = (request: Request): number | null => {
  const header = request.headers.get('content-length');
  if (!header) return null;
  const parsed = Number(header);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : null;
};

const readCappedRequestBody = async (request: Request, maxBytes: number): Promise<string> => {
  const contentLength = parseContentLength(request);
  if (contentLength !== null && contentLength > maxBytes) {
    throw new Error(`TOWER_BODY_TOO_LARGE: bytes=${contentLength} max=${maxBytes}`);
  }
  if (!request.body) return '';

  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!value) continue;
    total += value.byteLength;
    if (total > maxBytes) {
      throw new Error(`TOWER_BODY_TOO_LARGE: bytes=${total} max=${maxBytes}`);
    }
    chunks.push(value);
  }

  const buffer = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    buffer.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(buffer);
};

/** HTTP bytes are untrusted until the endpoint-specific decoder accepts them. */
const parseJsonBody = async (request: Request, maxBytes = DEFAULT_MAX_JSON_BODY_BYTES): Promise<unknown> => {
  const raw = await readCappedRequestBody(request, maxBytes);
  if (!raw.trim()) {
    throw new Error('TOWER_BODY_EMPTY');
  }
  return JSON.parse(raw) as unknown;
};

const decodeTowerRestoreRequest = (value: unknown): TowerRestoreRequestV1 => {
  const body = requireBoundaryRecord(value, 'TOWER_RESTORE_BODY_INVALID');
  requireExactBoundaryKeys(body, ['lookupKey'], [], 'TOWER_RESTORE_BODY_FIELDS_INVALID');
  return { lookupKey: normalizeLookupKey(body['lookupKey']) };
};

const decodeTowerRecord = (value: unknown, code: string): Record<string, unknown> =>
  requireBoundaryRecord(value, code);

/**
 * Decode the transport envelope before any signed appointment field is read.
 * Signature verification authenticates values; it must not also be asked to
 * compensate for malformed JSON structure or unexpected schema fields.
 */
const decodeTowerAppointmentEnvelope = (value: unknown): TowerAppointmentV1 => {
  const appointment = decodeTowerRecord(value, 'TOWER_APPOINTMENT_INVALID');
  requireExactBoundaryKeys(
    appointment,
    ['type', 'version', 'lookupKey', 'bundle', 'ownerProof'],
    ['towerMode', 'slot', 'lastResortPayload'],
    'TOWER_APPOINTMENT_FIELDS_INVALID',
  );
  if (appointment['type'] !== 'tower_appointment' || appointment['version'] !== 1) {
    throw new Error('TOWER_APPOINTMENT_INVALID');
  }
  const bundle = decodeTowerRecord(appointment['bundle'], 'TOWER_BUNDLE_INVALID');
  requireExactBoundaryKeys(
    bundle,
    ['version', 'runtimeId', 'lookupKey', 'height', 'createdAt', 'bundleHash', 'iv', 'ciphertext'],
    ['kind', 'baseRuntimeHeight', 'baseCheckpointHash', 'compression'],
    'TOWER_BUNDLE_FIELDS_INVALID',
  );
  const ownerProof = decodeTowerRecord(appointment['ownerProof'], 'TOWER_APPOINTMENT_OWNER_PROOF_INVALID');
  requireExactBoundaryKeys(
    ownerProof,
    ['runtimeId', 'signedAt', 'signature'],
    [],
    'TOWER_APPOINTMENT_OWNER_PROOF_FIELDS_INVALID',
  );
  const lastResortPayload = appointment['lastResortPayload'];
  if (lastResortPayload !== undefined) {
    const payload = decodeTowerRecord(lastResortPayload, 'TOWER_LAST_RESORT_PAYLOAD_INVALID');
    requireExactBoundaryKeys(
      payload,
      [
        'triggerHint', 'watch', 'encryptedRemedy', 'actionKind', 'appointmentSequence', 'proofNonce',
        'proofBodyHash', 'responseMode', 'lastResortWindowSeconds',
      ],
      ['maxFeeToken', 'feeBudget'],
      'TOWER_LAST_RESORT_PAYLOAD_FIELDS_INVALID',
    );
    const watch = decodeTowerRecord(payload['watch'], 'TOWER_LAST_RESORT_PAYLOAD_WATCH_MISSING');
    requireExactBoundaryKeys(
      watch,
      ['rpcUrl', 'chainId', 'depositoryAddress', 'watchedEntityId', 'counterentity'],
      [],
      'TOWER_LAST_RESORT_PAYLOAD_WATCH_FIELDS_INVALID',
    );
  }
  return appointment as TowerAppointmentV1;
};

const normalizeLookupKey = (lookupKey: unknown): string => {
  const value = String(lookupKey || '').trim().toLowerCase();
  if (!/^0x[0-9a-f]{64}$/.test(value)) {
    throw new Error(`TOWER_LOOKUP_KEY_INVALID: ${String(lookupKey)}`);
  }
  return value;
};

const normalizeBytes32 = (value: unknown, label: string): string => {
  const normalized = String(value || '').trim().toLowerCase();
  if (!/^0x[0-9a-f]{64}$/.test(normalized)) {
    throw new Error(`TOWER_${label}_INVALID: ${String(value)}`);
  }
  return normalized;
};

const normalizeHexBytes = (value: unknown, label: string): string => {
  const normalized = String(value || '').trim().toLowerCase();
  if (!/^0x([0-9a-f]{2})*$/.test(normalized)) {
    throw new Error(`TOWER_${label}_INVALID`);
  }
  return normalized;
};

const normalizeNonNegativeInt = (value: unknown, label: string): number => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new Error(`TOWER_${label}_INVALID`);
  }
  return Math.floor(parsed);
};

const quotaExceededStatus = (error: unknown, message: string): number =>
  error instanceof WatchtowerGlobalQuotaError ||
  message.startsWith('TOWER_QUOTA_EXCEEDED') ||
  message.startsWith('TOWER_BODY_TOO_LARGE') ? 413 : 400;

const verifyEncryptedBundleShape = (appointment: TowerAppointmentV1): void => {
  if (!appointment.bundle || appointment.bundle.version !== 1) {
    throw new Error('TOWER_BUNDLE_VERSION_UNSUPPORTED');
  }
  const runtimeId = String(appointment.bundle.runtimeId || '').trim().toLowerCase();
  if (!runtimeId) {
    throw new Error('TOWER_BUNDLE_RUNTIME_ID_REQUIRED');
  }
  normalizeLookupKey(appointment.bundle.lookupKey);
  normalizeNonNegativeInt(appointment.bundle.height, 'BUNDLE_HEIGHT');
  normalizeNonNegativeInt(appointment.bundle.createdAt, 'BUNDLE_CREATED_AT');
  normalizeBytes32(appointment.bundle.bundleHash, 'BUNDLE_HASH');
  normalizeHexBytes(appointment.bundle.iv, 'BUNDLE_IV');
  const ciphertext = normalizeHexBytes(appointment.bundle.ciphertext, 'BUNDLE_CIPHERTEXT');
  if (ciphertext.length <= 2) {
    throw new Error('TOWER_BUNDLE_CIPHERTEXT_EMPTY');
  }
  if (appointment.bundle.compression !== undefined && appointment.bundle.compression !== 'gzip') {
    throw new Error(`TOWER_BUNDLE_COMPRESSION_UNSUPPORTED: ${String(appointment.bundle.compression)}`);
  }
};

const assertEncryptedLastResortPayload = (lastResortPayload: TowerAppointmentV1['lastResortPayload']): void => {
  const raw = String(lastResortPayload?.encryptedRemedy || '').trim();
  if (!raw) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_MISSING');
  }
  let parsed: Record<string, unknown>;
  try {
    parsed = requireBoundaryRecord(deserializeTaggedJson(raw), 'TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  } catch {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  }
  if (
    parsed['type'] !== 'tower_encrypted_payload' ||
    parsed['version'] !== 1 ||
    parsed['alg'] !== 'watch-seed-aes-256-gcm' ||
    typeof parsed['iv'] !== 'string' ||
    typeof parsed['ciphertext'] !== 'string'
  ) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED');
  }
};

const verifyLastResortWatch = (watch: unknown): void => {
  if (!watch || typeof watch !== 'object') {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_WATCH_MISSING');
  }
  const candidate = watch as Record<string, unknown>;
  const rpcUrl = String(candidate['rpcUrl'] || '').trim();
  if (!rpcUrl || rpcUrl.length > 512 || !/^https?:\/\//i.test(rpcUrl)) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_WATCH_RPC_INVALID');
  }
  if (normalizeNonNegativeInt(candidate['chainId'], 'LAST_RESORT_PAYLOAD_WATCH_CHAIN_ID') <= 0) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_WATCH_CHAIN_ID_INVALID');
  }
  if (!ethers.isAddress(String(candidate['depositoryAddress'] || ''))) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_WATCH_DEPOSITORY_INVALID');
  }
  normalizeBytes32(candidate['watchedEntityId'], 'LAST_RESORT_PAYLOAD_WATCH_ENTITY');
  normalizeBytes32(candidate['counterentity'], 'LAST_RESORT_PAYLOAD_WATCH_COUNTERENTITY');
};

const verifyLastResortPayload = (lastResortPayload: TowerAppointmentV1['lastResortPayload']): void => {
  if (!lastResortPayload) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_MISSING');
  }
  if (lastResortPayload.actionKind !== 'counter_dispute_only') {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_ACTION_KIND_UNSUPPORTED');
  }
  if (lastResortPayload.responseMode !== 'last_resort') {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_RESPONSE_MODE_UNSUPPORTED');
  }
  verifyLastResortWatch(lastResortPayload.watch);
  const triggerHint = String(lastResortPayload.triggerHint || '').trim();
  if (!triggerHint || triggerHint.length > 256) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_TRIGGER_HINT_INVALID');
  }
  if (normalizeNonNegativeInt(lastResortPayload.appointmentSequence, 'LAST_RESORT_PAYLOAD_APPOINTMENT_SEQUENCE') <= 0) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_APPOINTMENT_SEQUENCE_INVALID');
  }
  if (normalizeNonNegativeInt(lastResortPayload.proofNonce, 'LAST_RESORT_PAYLOAD_PROOF_NONCE') <= 0) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_PROOF_NONCE_INVALID');
  }
  normalizeBytes32(lastResortPayload.proofBodyHash, 'LAST_RESORT_PAYLOAD_PROOF_BODY_HASH');
  if (normalizeNonNegativeInt(lastResortPayload.lastResortWindowSeconds, 'LAST_RESORT_PAYLOAD_LAST_RESORT_WINDOW') <= 0) {
    throw new Error('TOWER_LAST_RESORT_PAYLOAD_LAST_RESORT_WINDOW_INVALID');
  }
  assertEncryptedLastResortPayload(lastResortPayload);
};

const verifyTowerAppointment = (input: unknown): TowerAppointmentV1 => {
  const appointment = decodeTowerAppointmentEnvelope(input);
  if (!appointment || appointment.type !== 'tower_appointment' || appointment.version !== 1) {
    throw new Error('TOWER_APPOINTMENT_INVALID');
  }
  verifyEncryptedBundleShape(appointment);
  const lookupKey = normalizeLookupKey(appointment.lookupKey);
  if (appointment.bundle.lookupKey !== lookupKey) {
    throw new Error('TOWER_APPOINTMENT_LOOKUP_MISMATCH');
  }
  const runtimeId = String(appointment.ownerProof?.runtimeId || '').trim().toLowerCase();
  if (!runtimeId || runtimeId !== String(appointment.bundle.runtimeId || '').trim().toLowerCase()) {
    throw new Error('TOWER_APPOINTMENT_RUNTIME_ID_MISMATCH');
  }
  const signedAt = Math.max(0, Math.floor(Number(appointment.ownerProof?.signedAt || 0)));
  if (!Number.isSafeInteger(signedAt) || signedAt <= 0) {
    throw new Error('TOWER_APPOINTMENT_SIGNED_AT_INVALID');
  }
  if (Math.abs(Date.now() - signedAt) > TOWER_APPOINTMENT_MAX_CLOCK_SKEW_MS) {
    throw new Error('TOWER_APPOINTMENT_STALE');
  }
  const slot = Math.max(0, Math.floor(Number(appointment.slot ?? 0)));
  const towerMode = normalizeTowerModeV1(appointment.towerMode);
  if (towerMode === 'blind_backup' && appointment.lastResortPayload) {
    throw new Error('TOWER_BACKUP_LAST_RESORT_PAYLOAD_FORBIDDEN');
  }
  if (towerMode === 'delayed_last_resort') {
    verifyLastResortPayload(appointment.lastResortPayload);
  }
  const message = buildTowerAppointmentOwnerMessage(
    runtimeId,
    towerMode,
    lookupKey,
    slot,
    appointment.bundle,
    signedAt,
    appointment.lastResortPayload,
  );
  const recovered = ethers.verifyMessage(message, String(appointment.ownerProof?.signature || '')).toLowerCase();
  if (recovered !== runtimeId) {
    throw new Error(`TOWER_APPOINTMENT_SIGNATURE_INVALID: recovered=${recovered} expected=${runtimeId}`);
  }
  return {
    ...appointment,
    towerMode,
    lookupKey,
    slot,
    ownerProof: {
      ...appointment.ownerProof,
      runtimeId,
      signedAt,
      signature: String(appointment.ownerProof.signature || ''),
    },
    bundle: {
      ...appointment.bundle,
      runtimeId,
      lookupKey,
      height: Math.max(0, Math.floor(Number(appointment.bundle.height || 0))),
      createdAt: Math.max(0, Math.floor(Number(appointment.bundle.createdAt || 0))),
    },
  };
};

const errorResponse = (error: unknown): Response => {
  const message = error instanceof Error ? error.message : String(error);
  return new Response(
    serializeTaggedJson({ ok: false, error: message }),
    {
      status: quotaExceededStatus(error, message),
      headers: { 'content-type': 'application/json' },
    },
  );
};

export const handleTowerAppointment = async (req: Request, store: WatchtowerStore): Promise<Response> => {
  try {
    // The HTTP envelope must be able to carry any bundle that the configured
    // storage quota can accept. Keep a bounded allowance for signatures and
    // appointment metadata; the store still enforces the authoritative quota.
    const body = await parseJsonBody(req, resolveAppointmentBodyLimit(store));
    if (Array.isArray(body) && body.length !== 2) throw new Error('TOWER_ARCHIVE_PAIR_INVALID');
    const receipt = Array.isArray(body)
      ? await store.upsertRecoveryArchive([verifyTowerAppointment(body[0]), verifyTowerAppointment(body[1])])
      : await store.upsertAppointment(verifyTowerAppointment(body));
    return new Response(serializeTaggedJson({ ok: true, receipt }), {
      headers: { 'content-type': 'application/json' },
    });
  } catch (error) {
    return errorResponse(error);
  }
};

